             49444,43551,36421,33462,44066,48984,33485,37419,48581,43237,49366,33461,43940,48947,33706,
             44691,49615,49315,49919,43422,43499,49629,49314,49313,49630,49446,49704,49706,49635,49316,
             37416,34052,34364,42081,33466,43238)
ORDER BY card_id